<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue';
import type {DoudizhuRoomView,Card} from '@board/contracts';
import {getHandType} from '@board/game-core/landlord-hand';
import RoleBadge from '../components/RoleBadge.vue';
import AccountPanel from '../components/AccountPanel.vue';
const user=ref<{nickname:string}|null>(null),room=ref<DoudizhuRoomView|null>(null),rooms=ref<DoudizhuRoomView[]>([]);
const capacity=ref(3),code=ref(''),error=ref(''),busy=ref(false),uncertain=ref(false),copied=ref(false),confirmEnd=ref(false);
const selection=ref<string[]>([]),showRules=ref(false),handElement=ref<HTMLElement>();
const viewport=ref({width:window.innerWidth,height:window.innerHeight}),handWidth=ref(1000),tick=ref(performance.now());
let clockAnchor={server:Date.now(),local:performance.now()},animationTimer:ReturnType<typeof setInterval>|undefined,handObserver:ResizeObserver|undefined;
const remaining=computed(()=>{const r=room.value;if(!r?.deadline)return null;return Math.max(0,Math.min(r.turnSeconds,Math.ceil((r.deadline-clockAnchor.server-(tick.value-clockAnchor.local))/1000)));});
const needsRotate=computed(()=>!!room.value&&viewport.value.width<900&&viewport.value.height>viewport.value.width);
const fullscreenMessage=ref('');
async function landscape(){try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();const orientation=screen.orientation as ScreenOrientation & {lock?:(mode:string)=>Promise<void>};if(orientation.lock)await orientation.lock('landscape');else fullscreenMessage.value='请把手机横过来，浏览器不支持自动锁定。';}catch{fullscreenMessage.value='请把手机横过来；当前浏览器不支持自动锁定。';}}
const isPortrait=computed(()=>viewport.value.width<600&&viewport.value.height>viewport.value.width);
const handRows=computed(()=>{const n=isPortrait.value&&hand.value.length>10?Math.ceil(hand.value.length/2):hand.value.length||1;return Array.from({length:Math.ceil(hand.value.length/n)},(_,i)=>hand.value.slice(i*n,(i+1)*n));});
const cardHeight=computed(()=>isPortrait.value?Math.max(80,Math.min(106,viewport.value.height*.125)):Math.max(86,Math.min(206,viewport.value.height*.235)));
const cardWidth=computed(()=>Math.round(cardHeight.value*.68));
const opponents=computed(()=>{const r=room.value;if(!r)return [];return [1,2].map(offset=>({seat:(r.yourSeat+offset)%3,side:offset===1?'right':'left'})).map(s=>({...s,player:r.seats.find(p=>p.seat===s.seat)}));});
const tablePlay=(seat:number)=>room.value?.tablePlays?.[seat];
function playRows(seat:number){const cards=tablePlay(seat)?.cards??[],n=viewport.value.width<600?6:10;return Array.from({length:Math.ceil(cards.length/n)},(_,i)=>cards.slice(i*n,(i+1)*n));}
function rowStyle(length:number){return {'--step':`${length>1?Math.max(0,(handWidth.value-cardWidth.value)/(length-1)):0}px`};}
function resize(){viewport.value={width:window.innerWidth,height:window.innerHeight};}
watch(handElement,el=>{handObserver?.disconnect();if(!el)return;handWidth.value=el.clientWidth;handObserver=new ResizeObserver(entries=>{handWidth.value=entries[0]!.contentRect.width;});handObserver.observe(el);});
let epoch=0,stopped=false,timer:ReturnType<typeof setTimeout>|undefined;
const suits:Record<string,string>={hearts:'♥',diamonds:'♦',clubs:'♣',spades:'♠',joker_red:'大王',joker_black:'小王'};
const face=(c:Card)=>c.rank==='JOKER'?(c.suit==='joker_red'?'大王':'小王'):c.rank;
const label=(c:Card)=>(c.rank==='JOKER'?'':suits[c.suit])+face(c);
const symbol=(c:Card)=>c.rank==='JOKER'?'王':suits[c.suit];
const red=(c:Card)=>['hearts','diamonds','joker_red'].includes(c.suit);
const typeNames:Record<string,string>={single:'单张',pair:'对子',triple:'三张',triple_one:'三带一',triple_two:'三带二',straight:'顺子',double_straight:'连对',plane:'飞机',plane_single:'飞机带单',plane_pair:'飞机带对',four_two:'四带二',four_two_pair:'四带两对',bomb:'炸弹',rocket:'王炸'};
const state=computed(()=>room.value?.view),hand=computed(()=>state.value?.myHand??[]);
const selectedType=computed(()=>{const cards=hand.value.filter(c=>selection.value.includes(c.id));return cards.length?getHandType(cards):null;});
const isBid=computed(()=>room.value?.status==='playing'&&state.value?.biddingInfo.myTurnToBid);
const canPass=computed(()=>canAct.value&&!!state.value?.gameInfo.lastPlay&&state.value.gameInfo.lastPlayer!==room.value?.yourSeat);
const mine=computed(()=>room.value?.seats.find(s=>s.seat===room.value?.yourSeat));
const isTurn=computed(()=>room.value?.status==='playing'&&state.value?.currentPhase==='playing'&&state.value.currentTurn===room.value.yourSeat);
const canAct=computed(()=>isTurn.value&&!busy.value&&!uncertain.value&&remaining.value!==0);
const turnLabel=computed(()=>{const r=room.value;if(!r)return '';if(r.status==='waiting')return '三人到齐，准备开局';if(r.status==='cancelled')return '房间已取消';if(r.status==='finished')return r.reason==='resign'?'本局已结束':state.value?.winner==='landlord'?'地主获胜！':'农民获胜！';const name=r.seats.find(s=>s.seat===state.value?.currentTurn)?.name??'好友';if(state.value?.currentPhase==='bidding')return isBid.value?'轮到你叫分':`等待 ${name} 叫分`;return isTurn.value?'轮到你出牌':`等待 ${name} 出牌`;});
class ApiError extends Error{constructor(message:string,public status:number){super(message);}}
async function api(path:string,body?:unknown){const r=await fetch(path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)}),signal:AbortSignal.timeout(10000)});const data=await r.json();if(!r.ok)throw new ApiError(data.error||'请求失败',r.status);return data;}
function clear(){selection.value=[];confirmEnd.value=false;}
function accept(next:DoudizhuRoomView){clockAnchor={server:next.serverNow??Date.now(),local:performance.now()};tick.value=performance.now();if(room.value?.version!==next.version||room.value?.code!==next.code)clear();room.value=next;uncertain.value=false;}
async function list(current=epoch){const data=await api('/api/doudizhu/rooms');if(current===epoch)rooms.value=data.rooms;}
async function account(){const current=++epoch;room.value=null;rooms.value=[];clear();try{const data=await api('/api/auth/me');if(current!==epoch)return;user.value=data.user;if(user.value)await list(current);}catch(e){if(current===epoch){user.value=null;error.value=e instanceof Error?e.message:'账号暂不可用';}}}
async function enter(join=false,key=code.value){if(busy.value)return;const current=++epoch;busy.value=true;error.value='';try{key=key.trim().toUpperCase();if(join&&!/^[A-F0-9]{10}$/.test(key))throw new Error('请输入好友发来的10位房间码');const data=await api(join?`/api/doudizhu/rooms/${key}/join`:'/api/doudizhu/rooms',join?{}:{capacity:capacity.value});if(current===epoch){clear();accept(data);copied.value=false;}}catch(e){if(current===epoch)error.value=e instanceof Error?e.message:'无法进入房间';}finally{busy.value=false;}}
async function resume(key:string){if(busy.value)return;busy.value=true;const current=++epoch;error.value='';try{const next=await api(`/api/doudizhu/rooms/${key}`);if(current===epoch)accept(next);}catch(e){if(current===epoch)error.value=e instanceof Error?e.message:'恢复失败';}finally{busy.value=false;}}
async function back(){epoch++;room.value=null;uncertain.value=false;clear();error.value='';if(user.value)try{await list();}catch(e){error.value=e instanceof Error?e.message:'暂时无法加载房间';}}
async function act(type:string,extra:object={}){if(!room.value||busy.value||uncertain.value)return;busy.value=true;error.value='';const current=epoch,key=room.value.code;
 try{const next=await api(`/api/doudizhu/rooms/${key}/actions`,{type,requestId:crypto.randomUUID(),expectedVersion:room.value.version,...extra});if(current===epoch&&key===room.value?.code){if(next.left)await back();else accept(next);}}
 catch(e){if(current===epoch){uncertain.value=true;clear();error.value=e instanceof Error?e.message:'操作未确认，正在同步';}}
 finally{busy.value=false;}
}
async function poll(){if(stopped)return;if(room.value&&user.value&&!busy.value){const current=epoch,key=room.value.code;try{const next=await api(`/api/doudizhu/rooms/${key}`);if(current===epoch&&room.value?.code===key&&!busy.value&&next.version>=room.value.version){if(uncertain.value)error.value='';accept(next);}}catch(e){if(current===epoch){uncertain.value=true;error.value=e instanceof Error?e.message:'连接中断，正在重试';if(e instanceof ApiError&&e.status===401){user.value=null;room.value=null;clear();window.dispatchEvent(new Event('boardgame:account-changed'));}}}}timer=setTimeout(poll,1200);}
function select(id:string){if(!canAct.value)return;const i=selection.value.indexOf(id);if(i>=0)selection.value.splice(i,1);else selection.value.push(id);error.value='';}
function play(){if(canAct.value&&selection.value.length)void act('play',{cards:[...selection.value]});}
async function copy(){try{await navigator.clipboard.writeText(room.value!.code);copied.value=true;}catch{error.value='请手动选择房间码复制';}}
onMounted(()=>{animationTimer=setInterval(()=>{tick.value=performance.now();},200);window.addEventListener('resize',resize);void account();void poll();window.addEventListener('boardgame:account-changed',account);});
onUnmounted(()=>{handObserver?.disconnect();clearInterval(animationTimer);window.removeEventListener('resize',resize);stopped=true;epoch++;clearTimeout(timer);window.removeEventListener('boardgame:account-changed',account);});
</script>

<template>
 <main class="doudizhu-page" :class="{'at-table':!!room}">
  <nav :inert="needsRotate"><button @click="back">← 首页</button><button v-if="room" @click="back">稍后继续</button><span class="nav-title">斗地主 <small>好友牌桌</small></span><div class="account"><AccountPanel compact /></div></nav>
  <p v-if="error" class="error" role="alert">{{error}}</p>
  <section v-if="!room" class="welcome">
   <div class="welcome-copy"><p class="kicker">三人一桌 · 一起出好牌</p><h1>一副好牌，<br>一桌老朋友。</h1><p class="intro">三人好友斗地主，各用自己的设备。<br>叫分争地主，搭档见默契。</p></div>
   <div class="brand-art" aria-hidden="true"><span>♠</span><span>♥</span></div>
   <div class="entry"><template v-if="user"><p>你好，{{user.nickname}}。创建牌桌，邀两位好友来坐。</p><div class="entry-actions"><button class="primary" :disabled="busy" @click="enter(false)">创建三人房间</button><span>或</span><form @submit.prevent="enter(true)"><label for="room-code">好友房间码</label><div><input id="room-code" v-model="code" maxlength="10" placeholder="10 位房间码" autocomplete="off"><button :disabled="busy">加入房间</button></div></form></div>
    <div v-if="rooms.length" class="resume"><h2>继续我的牌桌</h2><button v-for="r in rooms" :key="r.code" :disabled="busy" @click="resume(r.code)"><code>{{r.code}}</code> · {{r.status==='waiting'?'等待准备':r.status==='playing'?'对局中':'已结束'}} <span>继续 →</span></button></div></template>
    <template v-else><h2>先登录，再坐到一起。</h2><p>点击右上角“登录 / 注册”，用主站账号邀请好友。</p></template>
   </div>
  </section>

  <section v-if="room" class="game-room" :inert="needsRotate">
   <div class="room-strip"><span>第 {{room.round}} 局 <code>{{room.code}}</code><button class="copy" @click="copy" :aria-label="copied?'房间码已复制':'复制房间码'">{{copied?'已复制':'复制'}}</button></span><span class="rule-pill">30秒 / 回合</span><div><button class="fullscreen-button" @click="landscape">全屏</button><button @click="showRules=!showRules">牌桌说明</button><button v-if="room.status==='waiting'" :disabled="busy||uncertain" @click="act('leave')">离桌</button><button v-if="room.status==='playing'||(room.status==='waiting'&&room.hostSeat===room.yourSeat)" :disabled="busy||uncertain" @click="confirmEnd=true">{{room.status==='waiting'?'取消':'结束'}}</button></div></div>
   <div class="arena">
    <div class="felt-line" aria-hidden="true"></div>
    <div class="bottom-zone"><span class="small-label">{{state?.currentPhase==='bidding'?(state.biddingInfo.round===1?'暗叫 · 底牌未亮':'明叫 · 底牌公开'):'底牌'}}</span><div class="bottom-cards"><template v-if="state?.bottomCards.length"><div v-for="c in state.bottomCards" :key="c.id" class="poker mini" :class="{red:red(c)}" :aria-label="label(c)"><b>{{face(c)}}</b><i>{{symbol(c)}}</i></div></template><div v-for="i in state?.bottomCards.length?0:3" :key="i" class="poker mini card-back" aria-label="未公开底牌"></div></div><span v-if="state?.gameInfo.baseScore" class="small-label">底分 {{state.gameInfo.baseScore}} · ×{{state.gameInfo.multiplier}}</span></div>
    <section v-for="opponent in opponents" :key="opponent.seat" class="opponent" :class="opponent.side" :aria-label="opponent.side==='left'?'左侧对手':'右侧对手'">
     <div class="seat-profile" :class="{active:room.status==='playing'&&state?.currentTurn===opponent.seat}"><div class="avatar" :class="{landlord:opponent.player?.role==='landlord'}"><RoleBadge v-if="opponent.player?.role" :role="opponent.player.role"/><span v-else>{{opponent.player?.name.slice(0,1)||'+'}}</span></div><strong :title="opponent.player?.name">{{opponent.player?.name||'等待好友'}}</strong><span class="role">{{opponent.player?(room.status==='waiting'?(opponent.player.ready?'已准备':'未准备'):opponent.player.role==='landlord'?'地主':opponent.player.role==='farmer'?'农民':'等待叫分'):'分享房间码加入'}}</span></div>
     <div v-if="opponent.player&&room.status!=='waiting'" class="opponent-deck"><span v-for="i in Math.min(5,opponent.player.cardCount)" :key="i" class="card-back" aria-hidden="true"></span><b>{{opponent.player.cardCount}}<small>张</small></b></div>
    </section>
    <section v-for="opponent in opponents" :key="'play-'+opponent.seat" class="table-play" :class="opponent.side" :aria-label="(opponent.player?.name||'好友')+'出的牌'">
     <template v-if="tablePlay(opponent.seat)"><p v-if="tablePlay(opponent.seat)?.type==='pass'" class="pass-label">{{tablePlay(opponent.seat)?.automatic?'超时 · 不出':'不出'}}</p><p v-else-if="tablePlay(opponent.seat)?.type==='bid'" class="bid-label">{{tablePlay(opponent.seat)?.score?'叫 '+tablePlay(opponent.seat)?.score+' 分':'不叫'}}<small v-if="tablePlay(opponent.seat)?.automatic">超时</small></p><div v-else class="played-fan"><div v-for="(cards,rowIndex) in playRows(opponent.seat)" :key="rowIndex" class="played-row"><div v-for="c in cards" :key="c.id" class="poker mini" :class="{red:red(c)}" :aria-label="label(c)"><b>{{face(c)}}</b><i>{{symbol(c)}}</i></div></div><span v-if="tablePlay(opponent.seat)?.automatic" class="small-label">超时自动出牌</span></div></template>
    </section>
    <div class="center-status"><div v-if="remaining!==null&&room.status==='playing'" class="countdown" :class="{urgent:remaining<=5}" role="timer" aria-label="当前回合剩余秒数">{{remaining}}<small>秒</small></div><span v-else class="table-mark" aria-hidden="true">♠</span><h1 role="status">{{uncertain?'正在重新连接…':turnLabel}}</h1><p v-if="room.status==='waiting'">邀两位好友入座，准备好就开局。</p><p v-else-if="state?.currentPhase==='bidding'">当前最高 {{state.biddingInfo.highestBid}} 分</p><p v-else-if="room.status==='playing'">{{state?.gameInfo.lastPlay?'请接牌，或选择不出':'自由出牌'}}</p><p v-else-if="room.status==='finished'">{{room.reason==='resign'?'本局由玩家主动结束':'好牌，也要好搭档。'}}</p></div>
    <section class="table-play self-play" aria-label="我出的牌"><template v-if="tablePlay(room.yourSeat)"><p v-if="tablePlay(room.yourSeat)?.type==='pass'" class="pass-label">{{tablePlay(room.yourSeat)?.automatic?'超时 · 不出':'不出'}}</p><p v-else-if="tablePlay(room.yourSeat)?.type==='bid'" class="bid-label">{{tablePlay(room.yourSeat)?.score?'叫 '+tablePlay(room.yourSeat)?.score+' 分':'不叫'}}</p><div v-else class="played-fan"><div v-for="(cards,rowIndex) in playRows(room.yourSeat)" :key="rowIndex" class="played-row"><div v-for="c in cards" :key="c.id" class="poker mini" :class="{red:red(c)}" :aria-label="label(c)"><b>{{face(c)}}</b><i>{{symbol(c)}}</i></div></div><span v-if="tablePlay(room.yourSeat)?.automatic" class="small-label">超时自动出牌</span></div></template></section>
   </div>
   <div class="action-bar">
    <template v-if="room.status==='waiting'"><button class="primary" :disabled="busy||uncertain" @click="act('ready',{ready:!mine?.ready})">{{mine?.ready?'取消准备':'我准备好了'}}</button><span class="action-note">{{room.seats.length}} / 3 人入座</span></template>
    <template v-else-if="room.status==='playing'&&state?.currentPhase==='bidding'"><button :disabled="!isBid||busy||uncertain||remaining===0" @click="act('bid',{score:0})">不叫</button><button v-for="score in [1,2,3]" :key="score" class="primary" :disabled="!isBid||busy||uncertain||remaining===0||score<=state.biddingInfo.highestBid" @click="act('bid',{score})">{{score}} 分</button></template>
    <template v-else-if="room.status==='playing'"><button class="primary" :disabled="!canAct||!selectedType" @click="play">{{busy?'确认中…':selection.length?'出牌 · '+selection.length+' 张':'出牌'}}</button><button class="pass-button" :disabled="!canPass" @click="act('pass')">不出</button><button :disabled="!selection.length" @click="clear">重选</button><span class="action-note">{{selection.length?(selectedType?typeNames[selectedType.type]:'组合不是有效牌型'):isTurn?'点选手牌，选好后出牌':'等待对手'}}</span></template>
    <template v-else-if="room.status==='finished'"><button v-if="room.yourSeat===room.hostSeat" class="primary" :disabled="busy||uncertain" @click="act('rematch')">再来一局</button><span v-else class="action-note">等待房主开启下一局</span><button @click="back">离开牌桌</button></template><button v-else @click="back">返回房间列表</button>
   </div>
   <div class="hand-zone" :style="{'--card-h':cardHeight+'px','--card-w':cardWidth+'px'}"><div class="my-profile"><div class="avatar" :class="{landlord:mine?.role==='landlord'}"><RoleBadge v-if="mine?.role" :role="mine.role"/><span v-else>你</span></div><strong :title="mine?.name">{{mine?.name}}</strong><span class="role">{{mine?.role==='landlord'?'地主':mine?.role==='farmer'?'农民':'等待开局'}}</span><small>{{hand.length}} 张</small></div><div ref="handElement" class="hand-fan" aria-label="我的手牌"><div v-for="(cards,rowIndex) in handRows" :key="rowIndex" class="hand-row" :style="rowStyle(cards.length)"><button v-for="(c,i) in cards" :key="c.id" class="poker hand-card" :class="{selected:selection.includes(c.id),red:red(c),joker:c.rank==='JOKER'}" :style="{'--index':i}" :aria-label="label(c)" :aria-pressed="selection.includes(c.id)" :disabled="!canAct" @click="select(c.id)"><span class="corner"><b>{{face(c)}}</b><i>{{symbol(c)}}</i></span><span class="pip">{{symbol(c)}}</span><span class="corner corner-bottom"><b>{{face(c)}}</b><i>{{symbol(c)}}</i></span></button></div><p v-if="!hand.length" class="empty-hand">{{room.status==='waiting'?'准备好，等好友一起发牌。':'本局手牌已出完'}}</p></div></div>
   <aside v-if="showRules" class="rules-drawer" aria-label="牌桌说明"><button class="close" @click="showRules=false">关闭</button><h2>牌桌说明</h2><p>三人、54张牌，每人17张，留3张底牌。先暗叫；首轮无人叫分则亮底牌再叫，第二轮仍无人叫分则重发。叫分须递增，3分直接确定地主。</p><p>地主拿底牌先出。单张、对子、三带、顺子、连对、飞机、四带二、炸弹、王炸沿原版规则。两家不出后恢复自由出牌；四带二允许带一对。地主与两名农民分队，先出完的一方获胜。</p><p>每回合30秒：超时叫分默认不叫，跟牌默认不出；自由领出时自动出最小单张。倒计时由服务器裁决，刷新不会重置。可用“稍后继续”离开，座位保留但计时继续。</p><p>保留炸弹倍数，本版没有春天、正式积分、余额或金钱结算。</p></aside>
   <div v-if="confirmEnd" class="confirm-panel" role="alert"><p>{{room.status==='waiting'?'确定取消这个房间？':'这会结束所有人的对局。只是暂时离开，请用“稍后继续”。'}}</p><button :disabled="busy" @click="act(room.status==='waiting'?'cancel':'resign')">确认结束</button><button @click="confirmEnd=false">返回对局</button></div>
  </section>
  <details v-if="!room" class="rules"><summary>这张牌桌怎么玩？</summary><p>三人、54张牌，每人17张，留3张底牌。先暗叫；首轮无人叫分则亮底牌再叫，第二轮仍无人叫分则重发。叫分须递增，3分直接确定地主。</p><p>地主拿底牌先出。单张、对子、三带、顺子、连对、飞机、四带二、炸弹、王炸沿原版规则。两家不出后恢复自由出牌；四带二允许带一对。地主与两名农民分队，先出完的一方获胜。</p><p>每回合30秒：超时叫分默认不叫，跟牌默认不出；自由领出时自动出最小单张。倒计时由服务器裁决，刷新不会重置。可用“稍后继续”离开，座位保留但计时继续。</p><p>保留炸弹倍数，本版没有春天、正式积分、余额或金钱结算。</p></details>
 <section v-if="needsRotate" class="rotate-gate" aria-label="请横屏游玩"><span class="rotate-phone" aria-hidden="true">▯ ↻</span><h2>横过来，才好出牌。</h2><p>两位对手、出牌区和全部手牌<br>都在同一张横屏牌桌里。</p><button class="primary" @click="landscape">进入横屏牌桌</button><p class="rotate-note">{{fullscreenMessage||'请旋转手机；支持的浏览器会自动锁定横屏。'}}</p><button @click="back">返回房间列表</button></section>
 </main>
